public class CanteenRestock {String itemName;int stock;CanteenRestock(String itemName,int stock){this.itemName=itemName;this.stock=stock;}void restock(int stock){this.stock+=stock;}public static void main(String[]x){String[]n={"Samosa","Tea Powder","Bread","Biscuit Packs"};int[]s={15,40,8,25};for(int i=0;i<s.length;i++){CanteenRestock a=new CanteenRestock(n[i],s[i]);a.restock(20);System.out.println(a.itemName+" | Final Stock: "+a.stock);}}}
